<script>
	import { onMount } from 'svelte'; import { api } from '$lib/api.js'; import Nav from '$lib/Nav.svelte';
	let products = $state([]), loading = $state(true), errorMessage = $state(''), search = $state('');
	async function loadProducts() { loading = true; errorMessage = ''; try { const data = await api.getProducts(search ? { search } : {}); products = data.data ?? data ?? []; } catch (error) { errorMessage = error?.message || 'Unable to load products'; } finally { loading = false; } } onMount(loadProducts);
</script>

<Nav /><main class="app-page"><header class="page-heading"><div><p class="eyebrow">INVENTORY</p><h1>Products</h1><p>Browse products, prices and current stock levels.</p></div><a class="btn btn-primary" href="/products/create">＋ Add product</a></header><form class="toolbar" onsubmit={(event)=>{event.preventDefault();loadProducts();}}><input class="control search" placeholder="Search name, SKU or barcode…" bind:value={search}/><button class="btn" type="submit">Search</button></form><section class="panel">{#if loading}<div class="state">Loading products…</div>{:else if errorMessage}<div class="state error">{errorMessage}</div>{:else if products.length === 0}<div class="state"><h3>No products found</h3><p>Add your first product to begin tracking inventory.</p></div>{:else}<table class="data-table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Stock</th><th>Cost</th><th>Selling price</th></tr></thead><tbody>{#each products as product (product.id)}<tr><td class="strong">{product.name}</td><td>{product.sku}</td><td>{product.category?.name || 'Uncategorised'}</td><td><span class="stock" class:low={product.is_low_stock}>{product.quantity}{product.is_low_stock ? ' · Low' : ''}</span></td><td>RM {product.cost_price}</td><td>RM {product.sell_price}</td></tr>{/each}</tbody></table>{/if}</section></main>
<style>.stock{font-weight:700;color:#087a55}.stock.low{color:#b42318}</style>